  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Piritrexim, which shares the 2,4-diaminopyrimidine and methoxybenzyl core with the query, has an estimated oral bioavailability of ~75% in patients, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Indomethacin, containing a chloroindole and methoxyaryl motif similar to the query, has an absolute bioavailability of 80% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alfuzosin, a dimethoxyaryl aminoheterocycle, has an absolute bioavailability of 49% under fed conditions in healthy volunteers, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Fostamatinib, a high-molecular-weight prodrug with dimethoxyaniline and aminopyrimidine features, has an absolute oral bioavailability of 54.6% in humans, showing that physicochemical complexity does not preclude F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Alisertib, an aminopyrimidine with chloroaryl and methoxy substituents, has a bioavailability of 0.671 in pediatric patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Metoclopramide, a methoxybenzamide with chloro and amine groups, has an absolute bioavailability of 79 ± 19% in patients with severe alcoholic cirrhosis, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the physicochemical prior is unfavorable due to high MW, TPSA, and lipophilicity, multiple high-transfer experimental analogues sharing key structural features (2,4-diaminopyrimidine, dimethoxyaryl, chloroindole, amide) consistently show absolute oral bioavailability of 39-82%, all above the 20% threshold. The experimental evidence outweighs the prior, so the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "The query's high TPSA and low solubility could reduce absorption, but high-transfer analogues with similar features still exceeded 20%.",
    "Potential efflux or first-pass metabolism liabilities of the query were not directly tested in the available evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

